questions.answer:
async function fetchWithTimeout(url, ms = 5000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ms);

  try {
    const res = await fetch(url, { signal: controller.signal });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return res;
  } finally {
    clearTimeout(timer);
  }
}

fetchWithTimeout("https://api.example.com/slow", 100)
  .catch((err) => console.log(err.name));
// AbortError

fetch has no timeout option, so the timer aborts the controller and the pending fetch rejects. The finally block clears the timer on both success and failure; without it, Node keeps the event loop alive until the timer fires, and a browser tab holds a needless callback. A signal is one-shot, so create the controller inside the function, not at module scope. Modern alternative: fetch(url, { signal: AbortSignal.timeout(ms) }), which rejects with TimeoutError, making a timeout distinguishable from a user cancel.

